    90→void UPlacementHUDWidgetBase::PopulateCatalog(UWjWorldPlaceableObjectDataAsset* Catalog)
    91→{
    92→	if (!CatalogScrollBox || !Catalog)
    93→	{
    94→		return;
    95→	}
    96→
    97→	CatalogScrollBox->ClearChildren();
    98→	ButtonToObjectIdMap.Empty();
    99→	BuyButtonToObjectIdMap.Empty();
   100→
   101→	// 로비 컨텍스트일 때만 소유권/가격 정보 표시
   102→	const bool bIsLobby = (GetCurrentContext() == EPlacementContext::Lobby);
   103→	UWjWorldCosmeticSubsystem* CosmeticSub = nullptr;
   104→	int32 CoinBalance = 0;
   105→	int32 TotalPlacedCount = 0;
   106→	int32 MaxTotalPlaced = 0;
   107→
   108→	if (bIsLobby)
   109→	{
   110→		UGameInstance* GI = GetGameInstance();
   111→		if (GI)
   112→		{
   113→			CosmeticSub = GI->GetSubsystem<UWjWorldCosmeticSubsystem>();
   114→			UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>();
   115→			if (CurrencySub)
   116→			{
   117→				CoinBalance = CurrencySub->GetBalance(ECurrencyType::Coin);
   118→			}
   119→		}
   120→
   121→		const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   122→		if (Settings)
   123→		{
   124→			MaxTotalPlaced = Settings->MaxTotalLobbyPlacedObjects;
   125→		}
   126→
   127→		if (PlacementComponent)
   128→		{
   129→			IWjWorldPlacementDataProvider* DataProvider = PlacementComponent->GetPlacementDataProvider();
   130→			if (DataProvider)
   131→			{
   132→				TotalPlacedCount = DataProvider->GetPlacedObjects().Num();
   133→			}
   134→		}
   135→	}
   136→
   137→	const bool bTotalLimitReached = (MaxTotalPlaced > 0 && TotalPlacedCount >= MaxTotalPlaced);
   138→
   139→	for (const FPlaceableObjectDefinition& Def : Catalog->Objects)
   140→	{
   141→		const bool bIsPaidItem = (bIsLobby && Def.CoinPrice > 0 && Def.SteamItemDefId > 0);
   142→		int32 OwnedQty = (bIsPaidItem && CosmeticSub) ? CosmeticSub->GetItemQuantityByDefId(Def.SteamItemDefId) : 0;
   143→		const bool bOwned = (!bIsPaidItem || OwnedQty > 0);
   144→
   145→		// ---- 행 컨테이너 (HorizontalBox) ----
   146→		UHorizontalBox* Row = NewObject<UHorizontalBox>(this);
   147→
   148→		// ---- 아이템 선택 버튼 ----
   149→		UButton* ItemButton = NewObject<UButton>(this);
   150→		UTextBlock* ItemText = NewObject<UTextBlock>(this);
   151→
   152→		FString DisplayStr = Def.DisplayName.IsEmpty() ? Def.ObjectId.ToString() : Def.DisplayName.ToString();
   153→
   154→		// 소유 중 + 배치 상한: 현재/최대 표시
   155→		if (bIsLobby && bOwned && Def.MaxPlacementCount > 0 && PlacementComponent)
   156→		{
   157→			int32 PlacedCount = PlacementComponent->CountPlacedObjectsByType(Def.ObjectId);
   158→			DisplayStr += FString::Printf(TEXT("  [%d/%d]"), PlacedCount, Def.MaxPlacementCount);
   159→		}
   160→
   161→		ItemText->SetText(FText::FromString(DisplayStr));
   162→
   163→		FSlateFontInfo FontInfo = ItemText->GetFont();
   164→		FontInfo.Size = 14;
   165→		ItemText->SetFont(FontInfo);
   166→
   167→		// 미소유 아이템: 회색 처리
   168→		if (bIsPaidItem && !bOwned)
   169→		{
   170→			ItemText->SetColorAndOpacity(FSlateColor(FLinearColor(0.5f, 0.5f, 0.5f)));
   171→		}
   172→
   173→		ItemButton->AddChild(ItemText);
   174→		Row->AddChild(ItemButton);
   175→
   176→		// 아이템 버튼 Fill (나머지 공간 차지)
   177→		if (UHorizontalBoxSlot* ItemSlot = Cast<UHorizontalBoxSlot>(ItemButton->Slot))
   178→		{
   179→			ItemSlot->SetSize(FSlateChildSize(ESlateSizeRule::Fill));
   180→		}
   181→
   182→		ButtonToObjectIdMap.Add(ItemButton, Def.ObjectId);
   183→		ItemButton->OnClicked.AddDynamic(this, &UPlacementHUDWidgetBase::OnCatalogButtonClicked);
   184→
   185→		// ---- 구매 버튼 (미소유 유료 아이템만) ----
   186→		if (bIsPaidItem && !bOwned)
   187→		{
   188→			UButton* BuyButton = NewObject<UButton>(this);
   189→			UTextBlock* BuyText = NewObject<UTextBlock>(this);
   190→
   191→			BuyText->SetText(FText::FromString(FString::Printf(TEXT("%d Coin"), Def.CoinPrice)));
   192→
   193→			FSlateFontInfo BuyFont = BuyText->GetFont();
   194→			BuyFont.Size = 12;
   195→			BuyText->SetFont(BuyFont);
   196→
   197→			BuyButton->AddChild(BuyText);
   198→			Row->AddChild(BuyButton);
   199→
   200→			// 구매 가능 여부: 재화 충분 + 종류당 상한 미달 + 전체 상한 미달
   201→			bool bCanBuy = (CoinBalance >= Def.CoinPrice) && !bTotalLimitReached;
   202→
   203→			if (bCanBuy && Def.MaxPlacementCount > 0 && PlacementComponent)
   204→			{
   205→				int32 PlacedCount = PlacementComponent->CountPlacedObjectsByType(Def.ObjectId);
   206→				if (PlacedCount >= Def.MaxPlacementCount)
   207→				{
   208→					bCanBuy = false;
   209→				}
   210→			}
   211→
   212→			BuyButton->SetIsEnabled(bCanBuy);
   213→
   214→			BuyButtonToObjectIdMap.Add(BuyButton, Def.ObjectId);
   215→			BuyButton->OnClicked.AddDynamic(this, &UPlacementHUDWidgetBase::OnBuyButtonClicked);
   216→		}
   217→
   218→		CatalogScrollBox->AddChild(Row);
   219→	}
   220→
   221→	UpdateTotalPlacementCountText();
   222→
   223→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Catalog populated with %d items"), Catalog->Objects.Num());
   224→}
