   240→void UPlacementHUDWidgetBase::OnSaveClicked()
   241→{
   242→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementHUDWidgetBase: Save clicked"));
   243→
   244→	if (!SaveDialogClass)
   245→	{
   246→		// 다이얼로그 클래스가 없으면 기본 슬롯 이름으로 바로 저장
   247→		FString DefaultSlotName = GetCurrentLoadedSlotName();
   248→		if (DefaultSlotName.IsEmpty())
   249→		{
   250→			DefaultSlotName = GetSaveSlotNameForContext(GetCurrentContext());
   251→		}
   252→		ExecuteSave(DefaultSlotName);
   253→		return;
   254→	}
   255→
   256→	// 이미 열려있으면 스킵
   257→	if (SaveDialogInstance && SaveDialogInstance->IsInViewport())
   258→	{
   259→		return;
   260→	}
   261→
   262→	// 다이얼로그 생성
   263→	SaveDialogInstance = CreateWidget<UPlacementSaveDialogWidget>(GetOwningPlayer(), SaveDialogClass);
   264→	if (SaveDialogInstance)
   265→	{
   266→		// 로드된 슬롯 이름이 있으면 그것을 기본값으로, 없으면 컨텍스트 기본값 사용
   267→		FString DefaultSlotName = GetCurrentLoadedSlotName();
   268→		if (DefaultSlotName.IsEmpty())
   269→		{
   270→			DefaultSlotName = GetSaveSlotNameForContext(GetCurrentContext());
   271→		}
   272→		SaveDialogInstance->SetDefaultSlotName(DefaultSlotName);
   273→		SaveDialogInstance->SetContext(GetCurrentContext());
   274→
   275→		// 콜백 바인딩
   276→		SaveDialogInstance->OnSaveConfirmed.AddDynamic(this, &UPlacementHUDWidgetBase::OnSaveConfirmed);
   277→		SaveDialogInstance->ShowPopup();
   278→	}
   279→}
