   432→void UPlacementHUDWidgetBase::UpdateTotalPlacementCountText()
   433→{
   434→	if (!TotalPlacementCountText || !PlacementComponent)
   435→	{
   436→		return;
   437→	}
   438→
   439→	if (GetCurrentContext() != EPlacementContext::Lobby)
   440→	{
   441→		TotalPlacementCountText->SetVisibility(ESlateVisibility::Collapsed);
   442→		return;
   443→	}
   444→
   445→	const UWjWorldDeveloperSettings* Settings = GetDefault<UWjWorldDeveloperSettings>();
   446→	IWjWorldPlacementDataProvider* DataProvider = PlacementComponent->GetPlacementDataProvider();
   447→	if (!Settings || !DataProvider)
   448→	{
   449→		return;
   450→	}
   451→
   452→	int32 CurrentCount = DataProvider->GetPlacedObjects().Num();
   453→	int32 MaxCount = Settings->MaxTotalLobbyPlacedObjects;
   454→
   455→	if (MaxCount > 0)
   456→	{
   457→		TotalPlacementCountText->SetText(FText::FromString(FString::Printf(TEXT("%d/%d"), CurrentCount, MaxCount)));
   458→		TotalPlacementCountText->SetVisibility(ESlateVisibility::Visible);
   459→	}
   460→	else
   461→	{
   462→		TotalPlacementCountText->SetText(FText::FromString(FString::Printf(TEXT("%d"), CurrentCount)));
   463→		TotalPlacementCountText->SetVisibility(ESlateVisibility::Visible);
   464→	}
   465→}
