   348→void UWjWorldPlacementComponent::SaveLayout()
   349→{
   350→	// 호스트(ListenServer 또는 Standalone)인 경우에만 SaveGame 저장
   351→	// 클라이언트가 저장하면 다른 세션의 배치물이 섞이는 문제 발생
   352→	UWorld* World = GetWorld();
   353→	if (!World)
   354→	{
   355→		return;
   356→	}
   357→
   358→	ENetMode NetMode = World->GetNetMode();
   359→	if (NetMode != NM_Standalone && NetMode != NM_ListenServer)
   360→	{
   361→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: SaveLayout skipped (not host)"));
   362→		return;
   363→	}
   364→
   365→	// DataProvider에서 데이터를 가져와 로컬 SaveGame에 저장 (호스트 영구 저장용)
   366→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   367→	if (!DataProvider)
   368→	{
   369→		return;
   370→	}
   371→
   372→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   373→		UGameplayStatics::CreateSaveGameObject(UWjWorldLayoutSaveGame::StaticClass())
   374→	);
   375→
   376→	if (!SaveGame)
   377→	{
   378→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to create save game object"));
   379→		return;
   380→	}
   381→
   382→	// DataProvider의 배치 데이터 복사
   383→	SaveGame->PlacedObjects = DataProvider->GetPlacedObjects();
   384→
   385→	// 컨텍스트별 SaveSlot 이름 사용
   386→	FString SlotName = GetCurrentSaveSlotName();
   387→	if (UGameplayStatics::SaveGameToSlot(SaveGame, SlotName, 0))
   388→	{
   389→		UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout saved to '%s' (%d objects)"),
   390→			*SlotName, SaveGame->PlacedObjects.Num());
   391→	}
   392→	else
   393→	{
   394→		UE_LOG(LogWjWorldPlacement, Error, TEXT("PlacementComponent: Failed to save layout to '%s'"), *SlotName);
   395→	}
   396→}
