   464→bool UWjWorldPlacementComponent::LoadLayoutFromSlot(const FString& SlotName)
   465→{
   466→	UWorld* World = GetWorld();
   467→	if (!World)
   468→	{
   469→		return false;
   470→	}
   471→
   472→	// SaveGame 로드
   473→	UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   474→		UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   475→	);
   476→
   477→	if (!SaveGame)
   478→	{
   479→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Failed to load layout from '%s'"), *SlotName);
   480→		return false;
   481→	}
   482→
   483→	// 컨텍스트 검증 (다른 컨텍스트의 레이아웃 로드 방지)
   484→	if (SaveGame->SavedContext != EPlacementContext::None && SaveGame->SavedContext != CurrentContext)
   485→	{
   486→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: Context mismatch - slot '%s' is for '%s', current context is '%s'"),
   487→			*SlotName, *GetPlacementContextName(SaveGame->SavedContext), *GetPlacementContextName(CurrentContext));
   488→		return false;
   489→	}
   490→
   491→	// DataProvider가 있으면 데이터 설정
   492→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   493→	if (DataProvider)
   494→	{
   495→		// 일괄 설정 (RespawnAllPlacedObjects가 한 번만 호출됨)
   496→		DataProvider->SetPlacedObjects(SaveGame->PlacedObjects);
   497→	}
   498→
   499→	LoadedSlotName = SlotName;
   500→
   501→	// 로드된 오브젝트에 배치 모드 비주얼 적용
   502→	RefreshPlacementModeVisuals();
   503→
   504→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Layout loaded from '%s' (%d objects)"),
   505→		*SlotName, SaveGame->PlacedObjects.Num());
   506→	return true;
   507→}
