   509→TArray<FString> UWjWorldPlacementComponent::GetSavedLayoutSlots() const
   510→{
   511→	TArray<FString> SlotNames;
   512→
   513→	// SaveGame 디렉토리에서 모든 .sav 파일 검색
   514→	FString SaveDirectory = FPaths::ProjectSavedDir() / TEXT("SaveGames");
   515→
   516→	IFileManager& FileManager = IFileManager::Get();
   517→	TArray<FString> FoundFiles;
   518→	FileManager.FindFiles(FoundFiles, *SaveDirectory, TEXT("*.sav"));
   519→
   520→	for (const FString& FileName : FoundFiles)
   521→	{
   522→		// .sav 확장자 제거하여 슬롯 이름 추출
   523→		FString SlotName = FPaths::GetBaseFilename(FileName);
   524→
   525→		// SaveGame을 로드하여 컨텍스트 확인
   526→		UWjWorldLayoutSaveGame* SaveGame = Cast<UWjWorldLayoutSaveGame>(
   527→			UGameplayStatics::LoadGameFromSlot(SlotName, 0)
   528→		);
   529→
   530→		if (SaveGame && SaveGame->SavedContext == CurrentContext)
   531→		{
   532→			SlotNames.Add(SlotName);
   533→		}
   534→	}
   535→
   536→	UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Found %d saved layout slots for context '%s'"),
   537→		SlotNames.Num(), *GetPlacementContextName(CurrentContext));
   538→	return SlotNames;
   539→}
