   558→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   559→		}
   560→	}
   561→	// JumpMap 컨텍스트: CSV 파일도 삭제
   562→	else if (CurrentContext == EPlacementContext::JumpMap)
   563→	{
   564→		FString CSVPath = GetUserJumpMapLayoutDirectory() / SlotName + TEXT(".csv");
   565→		IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
