   569→			UE_LOG(LogWjWorldPlacement, Log, TEXT("PlacementComponent: Deleted CSV '%s'"), *CSVPath);
   570→		}
   571→	}
   572→
   573→	// 현재 로드된 슬롯이면 초기화
