   582→
   583→bool UWjWorldPlacementComponent::ExportLayoutAsCSV(const FString& FileName)
   584→{
   585→	// AW 컨텍스트에서만 동작
   586→	if (CurrentContext != EPlacementContext::ApproachingWall)
   587→	{
   588→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: Only available in ApproachingWall context"));
   589→		return false;
   590→	}
   591→
   592→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   593→	if (!DataProvider)
   594→	{
   595→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: No data provider"));
   596→		return false;
   597→	}
   598→
   599→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   600→	if (PlacedObjects.Num() == 0)
   601→	{
   602→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportLayoutAsCSV: No objects to export"));
   603→		return false;
   604→	}
   605→
   606→	// 그리드 설정 (기본값 사용, 추후 설정 가능하게 확장 가능)
   607→	const FApproachingWallGridConfig GridConfig;
   608→	const FVector& BrickSize = GridConfig.BrickSize;
   609→
   610→	// 1. 배치된 오브젝트의 바운딩 박스 계산
   611→	FVector MinBounds(FLT_MAX, FLT_MAX, FLT_MAX);
   612→	FVector MaxBounds(-FLT_MAX, -FLT_MAX, -FLT_MAX);
   613→
   614→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   615→	{
   616→		const FVector& Location = Entry.Transform.GetLocation();
   617→		MinBounds.X = FMath::Min(MinBounds.X, Location.X);
   618→		MinBounds.Y = FMath::Min(MinBounds.Y, Location.Y);
   619→		MaxBounds.X = FMath::Max(MaxBounds.X, Location.X);
   620→		MaxBounds.Y = FMath::Max(MaxBounds.Y, Location.Y);
   621→	}
   622→
   623→	// 2. 그리드 크기 계산 (+1 = 위치 개수, +2 = 양쪽 1셀 패딩)
   624→	int32 GridColumns = FMath::CeilToInt((MaxBounds.X - MinBounds.X) / BrickSize.X) + 1 + 2;
   625→	int32 GridRows = FMath::CeilToInt((MaxBounds.Y - MinBounds.Y) / BrickSize.Y) + 1 + 2;
   626→
   627→	// 최소 크기 보장
   628→	GridColumns = FMath::Max(GridColumns, 3);
   629→	GridRows = FMath::Max(GridRows, 3);
   630→
   631→	// 그리드 원점: MinBounds에서 1칸 앞 (패딩용, 오브젝트가 인덱스 1부터 매핑)
   632→	FVector GridOrigin = MinBounds - FVector(BrickSize.X, BrickSize.Y, 0.0f);
   633→
   634→	// 3. 그리드 초기화 (-1 = Empty)
   635→	TArray<TArray<int32>> Grid;
   636→	Grid.SetNum(GridRows);
   637→	for (int32 Row = 0; Row < GridRows; ++Row)
   638→	{
   639→		Grid[Row].SetNum(GridColumns);
   640→		for (int32 Col = 0; Col < GridColumns; ++Col)
   641→		{
   642→			Grid[Row][Col] = -1;
   643→		}
   644→	}
   645→
   646→	// 4. 오브젝트를 그리드에 매핑 (RoundToInt로 CalculateBrickGridIndex와 일치)
   647→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   648→	{
   649→		const FVector& Location = Entry.Transform.GetLocation();
   650→
   651→		// 월드 좌표 → 그리드 인덱스
   652→		int32 Col = FMath::RoundToInt((Location.X - GridOrigin.X) / BrickSize.X);
   653→		int32 Row = FMath::RoundToInt((Location.Y - GridOrigin.Y) / BrickSize.Y);
   654→
   655→		// 범위 체크
   656→		if (Row >= 0 && Row < GridRows && Col >= 0 && Col < GridColumns)
   657→		{
   658→			int32 BrickTypeValue = ObjectIdToBrickTypeValue(Entry.ObjectId);
   659→			Grid[Row][Col] = BrickTypeValue;
   660→		}
   661→	}
   662→
   663→	// 5. CSV 문자열 생성 (첫 줄에 메타데이터 포함)
   664→	FString CSVContent;
   665→
   666→	// ⭐ 메타데이터 헤더: CenterOffset 저장 (클라이언트 프리뷰 위치 동기화용)
   667→	// CalculateBrickPosition은 CenterOffset을 그리드 중심으로 사용하므로, 그리드 중심 좌표를 저장
   668→	FVector CenterOffset;
   669→	CenterOffset.X = GridOrigin.X + (GridColumns - 1) * 0.5f * BrickSize.X;
   670→	CenterOffset.Y = GridOrigin.Y + (GridRows - 1) * 0.5f * BrickSize.Y;
   671→	CenterOffset.Z = 0.0f;
   672→	CSVContent += FString::Printf(TEXT("#META:CenterOffset:%f,%f,%f\n"),
   673→		CenterOffset.X, CenterOffset.Y, CenterOffset.Z);
   674→
   675→	for (int32 Row = 0; Row < GridRows; ++Row)
   676→	{
   677→		for (int32 Col = 0; Col < GridColumns; ++Col)
   678→		{
   679→			CSVContent += FString::Printf(TEXT("%d"), Grid[Row][Col]);
   680→			if (Col < GridColumns - 1)
   681→			{
   682→				CSVContent += TEXT(",");
   683→			}
   684→		}
   685→		CSVContent += TEXT("\n");
   686→	}
   687→
   688→	// 6. 파일 저장
   689→	FString UserLayoutDir = GetUserWallLayoutDirectory();
   690→
   691→	// 디렉토리 생성
   692→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   693→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   694→	{
   695→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   696→	}
   697→
   698→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   699→
   700→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   701→	{
   702→		LastExportedCSVPath = FilePath;
   703→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportLayoutAsCSV: Exported to '%s' (Grid: %dx%d)"),
   704→			*FilePath, GridColumns, GridRows);
   705→		return true;
   706→	}
   707→	else
   708→	{
   709→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportLayoutAsCSV: Failed to save file '%s'"), *FilePath);
   710→		return false;
   711→	}
   712→}
