   714→bool UWjWorldPlacementComponent::ExportJumpMapLayoutAsCSV(const FString& FileName)
   715→{
   716→	if (CurrentContext != EPlacementContext::JumpMap)
   717→	{
   718→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: Only available in JumpMap context"));
   719→		return false;
   720→	}
   721→
   722→	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
   723→	if (!DataProvider)
   724→	{
   725→		UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: No data provider"));
   726→		return false;
   727→	}
   728→
   729→	const TArray<FPlacedObjectSaveEntry>& PlacedObjects = DataProvider->GetPlacedObjects();
   730→	if (PlacedObjects.Num() == 0)
   731→	{
   732→		UE_LOG(LogWjWorldPlacement, Warning, TEXT("ExportJumpMapLayoutAsCSV: No objects to export"));
   733→		return false;
   734→	}
   735→
   736→	// CSV 생성: 헤더 + 오브젝트 행 (11번째 Properties 컬럼 포함)
   737→	FString CSVContent;
   738→	CSVContent += FString::Printf(TEXT("#META:MapName:%s\n"), *FileName);
   739→	CSVContent += TEXT("ObjectId,PosX,PosY,PosZ,RotPitch,RotYaw,RotRoll,ScaleX,ScaleY,ScaleZ,Properties\n");
   740→
   741→	for (const FPlacedObjectSaveEntry& Entry : PlacedObjects)
   742→	{
   743→		const FVector& Loc = Entry.Transform.GetLocation();
   744→		const FRotator Rot = Entry.Transform.GetRotation().Rotator();
   745→		const FVector& Scale = Entry.Transform.GetScale3D();
   746→
   747→		// CustomProperties를 Key=Value|Key=Value 형식으로 직렬화
   748→		FString PropsStr;
   749→		for (const auto& Pair : Entry.CustomProperties)
   750→		{
   751→			if (!PropsStr.IsEmpty()) PropsStr += TEXT("|");
   752→			PropsStr += FString::Printf(TEXT("%s=%s"), *Pair.Key, *Pair.Value);
   753→		}
   754→
   755→		CSVContent += FString::Printf(TEXT("%s,%f,%f,%f,%f,%f,%f,%f,%f,%f,%s\n"),
   756→			*Entry.ObjectId.ToString(),
   757→			Loc.X, Loc.Y, Loc.Z,
   758→			Rot.Pitch, Rot.Yaw, Rot.Roll,
   759→			Scale.X, Scale.Y, Scale.Z,
   760→			*PropsStr);
   761→	}
   762→
   763→	// 파일 저장
   764→	FString UserLayoutDir = GetUserJumpMapLayoutDirectory();
   765→	IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
   766→	if (!PlatformFile.DirectoryExists(*UserLayoutDir))
   767→	{
   768→		PlatformFile.CreateDirectoryTree(*UserLayoutDir);
   769→	}
   770→
   771→	FString FilePath = UserLayoutDir / FileName + TEXT(".csv");
   772→	if (FFileHelper::SaveStringToFile(CSVContent, *FilePath))
   773→	{
   774→		LastExportedCSVPath = FilePath;
   775→		UE_LOG(LogWjWorldPlacement, Log, TEXT("ExportJumpMapLayoutAsCSV: Exported to '%s' (%d objects)"),
   776→			*FilePath, PlacedObjects.Num());
   777→		return true;
   778→	}
   779→
   780→	UE_LOG(LogWjWorldPlacement, Error, TEXT("ExportJumpMapLayoutAsCSV: Failed to save '%s'"), *FilePath);
   781→	return false;
   782→}
