   784→void UWjWorldPlacementComponent::TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction)
   785→{
   786→	Super::TickComponent(DeltaTime, TickType, ThisTickFunction);
   787→
   788→	if (CurrentMode == EPlacementMode::Placing && PreviewActor)
   789→	{
   790→		const FPlaceableObjectDefinition* Def = Catalog ? Catalog->FindByObjectId(SelectedObjectId) : nullptr;
   791→		float GroundOffset = Def ? Def->GroundOffset : 0.0f;
   792→		FVector PlaceLocation;
   793→		bool bTraceSuccess = false;
   794→
   795→		if (bAirPlacementMode)
   796→		{
   797→			// Air 모드: 수평 평면과 교차
   798→			FVector AirLocation;
   799→			if (TraceAirPlane(AirLocation))
   800→			{
   801→				PlaceLocation = AirLocation + FVector(0.0f, 0.0f, GroundOffset);
   802→				bTraceSuccess = true;
   803→			}
   804→		}
   805→		else
   806→		{
   807→			// Ground 모드: 기존 바닥 트레이스
   808→			FHitResult HitResult;
   809→			if (TraceGroundUnderMouse(HitResult))
   810→			{
   811→				PlaceLocation = HitResult.ImpactPoint + FVector(0.0f, 0.0f, GroundOffset);
   812→				bTraceSuccess = true;
   813→			}
   814→		}
   815→
   816→		if (bTraceSuccess)
   817→		{
   818→			// AW 컨텍스트: 그리드 스냅 적용
   819→			if (CurrentContext == EPlacementContext::ApproachingWall)
   820→			{
   821→				PlaceLocation = SnapToGrid(PlaceLocation);
   822→			}
   823→
   824→			FRotator PlaceRotation = PreviewActor->GetCurrentRotation();
   825→			PreviewActor->UpdatePreviewTransform(PlaceLocation, PlaceRotation);
   826→
   827→			// 유효성 검사
   828→			bCurrentPreviewValid = IsPlacementLocationValid(PlaceLocation);
   829→			PreviewActor->SetPreviewValid(bCurrentPreviewValid);
   830→		}
   831→		else
   832→		{
   833→			bCurrentPreviewValid = false;
   834→			PreviewActor->SetPreviewValid(false);
   835→		}
   836→
   837→		// 3D 회전 축 기즈모 표시
   838→		DrawRotationAxisGizmo();
   839→	}
   840→
   841→	// JumpMap 컨텍스트: 체크포인트 위에 CheckpointOrder 번호 3D 표시
   842→	if (CurrentContext == EPlacementContext::JumpMap && CurrentMode != EPlacementMode::None)
   843→	{
   844→		IWjWorldPlacementDataProvider* DP = GetPlacementDataProvider();
   845→		if (DP)
   846→		{
   847→			for (const FPlacedObjectSaveEntry& Obj : DP->GetPlacedObjects())
   848→			{
   849→				if (Obj.ObjectId.ToString().Contains(TEXT("Checkpoint")))
   850→				{
   851→					const FString* OrderStr = Obj.CustomProperties.Find(TEXT("CheckpointOrder"));
   852→					if (OrderStr)
   853→					{
   854→						FVector TextLoc = Obj.Transform.GetLocation() + FVector(0, 0, 200.f);
   855→						DrawDebugString(GetWorld(), TextLoc,
   856→							FString::Printf(TEXT("CP #%s"), **OrderStr),
   857→							nullptr, FColor::Yellow, 0.f, true, 1.5f);
   858→					}
   859→				}
   860→			}
   861→		}
   862→	}
   863→
   864→	if (CurrentMode == EPlacementMode::Deleting)
   865→	{
   866→		// 삭제 모드: 호버 대상 갱신
   867→		AWjWorldPlacedObjectActor* NewHovered = TraceForPlacedObject();
   868→
   869→		if (NewHovered != HoveredObject)
   870→		{
   871→			if (HoveredObject)
   872→			{
   873→				HoveredObject->SetHighlighted(false);
   874→			}
   875→			HoveredObject = NewHovered;
   876→			if (HoveredObject)
   877→			{
   878→				HoveredObject->SetHighlighted(true);
   879→			}
   880→		}
   881→	}
   882→}
