   884→bool UWjWorldPlacementComponent::TraceGroundUnderMouse(FHitResult& OutHit) const
   885→{
   886→	APlayerController* PC = GetPlayerController();
   887→	if (!PC)
   888→	{
   889→		return false;
   890→	}
   891→
   892→	FVector WorldLocation, WorldDirection;
   893→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
   894→	{
   895→		return false;
   896→	}
   897→
   898→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
   899→
   900→	FCollisionQueryParams QueryParams;
   901→	QueryParams.bTraceComplex = false;
   902→	QueryParams.AddIgnoredActor(GetOwner());
   903→	if (PreviewActor)
   904→	{
   905→		QueryParams.AddIgnoredActor(PreviewActor);
   906→	}
   907→
   908→	return GetWorld()->LineTraceSingleByChannel(OutHit, WorldLocation, TraceEnd, ECC_Visibility, QueryParams);
   909→}
   910→
   911→bool UWjWorldPlacementComponent::TraceAirPlane(FVector& OutLocation) const
   912→{
   913→	APlayerController* PC = GetPlayerController();
   914→	if (!PC)
   915→	{
   916→		return false;
   917→	}
   918→
   919→	FVector WorldLoc, WorldDir;
   920→	if (!PC->DeprojectMousePositionToWorld(WorldLoc, WorldDir))
   921→	{
   922→		return false;
   923→	}
   924→
   925→	// Ray-plane intersection: Plane at Z = AirPlaneHeight, Normal = UpVector
   926→	float Denom = FVector::DotProduct(WorldDir, FVector::UpVector);
   927→	if (FMath::Abs(Denom) < KINDA_SMALL_NUMBER)
   928→	{
   929→		return false; // 레이가 평면과 평행
   930→	}
   931→
   932→	float T = (AirPlaneHeight - WorldLoc.Z) / Denom;
   933→	if (T < 0.f || T > MaxAirTraceDistance)
   934→	{
   935→		return false; // 뒤쪽이거나 너무 먼 교차점
   936→	}
   937→
   938→	OutLocation = WorldLoc + WorldDir * T;
   939→	return true;
   940→}
   941→
   942→bool UWjWorldPlacementComponent::IsPlacementLocationValid(const FVector& Location) const
   943→{
   944→	UWorld* World = GetWorld();
   945→	if (!World)
   946→	{
   947→		return false;
   948→	}
   949→
   950→	// AW 컨텍스트: 그리드 스냅 사용 시 더 작은 반경으로 정확히 같은 위치만 체크
   951→	// 일반 컨텍스트: 기존 겹침 반경 사용
   952→	float CheckRadius = (CurrentContext == EPlacementContext::ApproachingWall)
   953→		? GridOverlapCheckRadius
   954→		: OverlapCheckRadius;
   955→
   956→	// 겹침 체크: 기존 배치된 오브젝트와 겹치는지
   957→	TArray<FOverlapResult> Overlaps;
   958→	FCollisionQueryParams QueryParams;
   959→	QueryParams.AddIgnoredActor(GetOwner());
   960→	if (PreviewActor)
   961→	{
   962→		QueryParams.AddIgnoredActor(PreviewActor);
   963→	}
   964→
   965→	FCollisionShape SphereShape = FCollisionShape::MakeSphere(CheckRadius);
   966→	World->OverlapMultiByChannel(Overlaps, Location, FQuat::Identity, ECC_Visibility, SphereShape, QueryParams);
   967→
   968→	for (const FOverlapResult& Overlap : Overlaps)
   969→	{
   970→		if (Cast<AWjWorldPlacedObjectActor>(Overlap.GetActor()))
   971→		{
   972→			return false;
   973→		}
   974→	}
   975→
   976→	return true;
   977→}
