   979→FVector UWjWorldPlacementComponent::SnapToGrid(const FVector& Location) const
   980→{
   981→	// AW 그리드 설정 사용
   982→	const FApproachingWallGridConfig GridConfig;
   983→	const FVector& BrickSize = GridConfig.BrickSize;
   984→
   985→	// 그리드 스냅: 각 축을 BrickSize 단위로 반올림
   986→	FVector SnappedLocation;
   987→	SnappedLocation.X = FMath::RoundToFloat(Location.X / BrickSize.X) * BrickSize.X;
   988→	SnappedLocation.Y = FMath::RoundToFloat(Location.Y / BrickSize.Y) * BrickSize.Y;
   989→	SnappedLocation.Z = Location.Z; // Z축은 스냅하지 않음 (바닥 높이 유지)
   990→
   991→	return SnappedLocation;
   992→}
