   994→AWjWorldPlacedObjectActor* UWjWorldPlacementComponent::TraceForPlacedObject() const
   995→{
   996→	APlayerController* PC = GetPlayerController();
   997→	if (!PC)
   998→	{
   999→		return nullptr;
  1000→	}
  1001→
  1002→	FVector WorldLocation, WorldDirection;
  1003→	if (!PC->DeprojectMousePositionToWorld(WorldLocation, WorldDirection))
  1004→	{
  1005→		return nullptr;
  1006→	}
  1007→
  1008→	FVector TraceEnd = WorldLocation + WorldDirection * TraceDistance;
  1009→
  1010→	FHitResult HitResult;
  1011→	FCollisionQueryParams QueryParams;
  1012→	QueryParams.bTraceComplex = false;
  1013→	QueryParams.AddIgnoredActor(GetOwner());
  1014→
  1015→	if (GetWorld()->LineTraceSingleByChannel(HitResult, WorldLocation, TraceEnd, ECC_Visibility, QueryParams))
  1016→	{
  1017→		return Cast<AWjWorldPlacedObjectActor>(HitResult.GetActor());
  1018→	}
  1019→
  1020→	return nullptr;
  1021→}
