  1039→void UWjWorldPlacementComponent::DrawRotationAxisGizmo() const
  1040→{
  1041→	UWorld* World = GetWorld();
  1042→	if (!World || !PreviewActor)
  1043→	{
  1044→		return;
  1045→	}
  1046→
  1047→	FVector Origin = PreviewActor->GetActorLocation();
  1048→	FVector AxisDir;
  1049→	FColor AxisColor;
  1050→	FString AxisName;
  1051→
  1052→	switch (PreviewActor->GetCurrentRotationAxis())
  1053→	{
  1054→	case EPlacementRotationAxis::Yaw:
  1055→		AxisDir = FVector::UpVector;
  1056→		AxisColor = FColor::Blue;
  1057→		AxisName = TEXT("Yaw (Z)");
  1058→		break;
  1059→	case EPlacementRotationAxis::Pitch:
  1060→		AxisDir = FVector::RightVector;
  1061→		AxisColor = FColor::Green;
  1062→		AxisName = TEXT("Pitch (Y)");
  1063→		break;
  1064→	case EPlacementRotationAxis::Roll:
  1065→		AxisDir = FVector::ForwardVector;
  1066→		AxisColor = FColor::Red;
  1067→		AxisName = TEXT("Roll (X)");
  1068→		break;
  1069→	}
  1070→
  1071→	FVector ArrowEnd = Origin + AxisDir * GizmoArrowLength;
  1072→	DrawDebugDirectionalArrow(World, Origin, ArrowEnd, GizmoArrowSize, AxisColor, false, -1.f, 0, GizmoArrowThickness);
  1073→
  1074→	// 반대 방향 짧은 선분 (양방향 축 표현)
  1075→	FVector OppositeEnd = Origin - AxisDir * (GizmoArrowLength * 0.3f);
  1076→	DrawDebugLine(World, Origin, OppositeEnd, AxisColor, false, -1.f, 0, GizmoArrowThickness * 0.5f);
  1077→
  1078→	// 축 이름 + 스냅 각도 텍스트 표시
  1079→	FString InfoText = FString::Printf(TEXT("%s | %.0f°"), *AxisName, GetEffectiveSnapDegrees());
  1080→	DrawDebugString(World, ArrowEnd + FVector(0.f, 0.f, 15.f), InfoText, nullptr, AxisColor, 0.f, true, 1.f);
  1081→}
