  1219→		}
  1220→		if (ToggleAirModeAction)
  1221→		{
  1222→			EIC->BindAction(ToggleAirModeAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnToggleAirModeAction);
  1223→		}
  1224→		if (CycleAxisAction)
  1225→		{
  1226→			EIC->BindAction(CycleAxisAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnCycleAxisAction);
  1227→		}
  1228→		if (CycleSnapAction)
  1229→		{
  1230→			EIC->BindAction(CycleSnapAction, ETriggerEvent::Started, this, &UWjWorldPlacementComponent::OnCycleSnapAction);
  1231→		}
  1232→	}
