  1390→	for (int32 i = 0; i < PlacedObjects.Num(); ++i)
  1391→	{
  1392→		const FPlacedObjectSaveEntry& Entry = PlacedObjects[i];
  1393→		if (Entry.ObjectId == TargetId)
  1394→		{
  1395→			// 위치가 가까우면 매치
  1396→			if (FVector::DistSquared(Entry.Transform.GetLocation(), TargetLocation) < 100.0f)
  1397→			{
  1398→				return i;
  1399→			}
  1400→		}
  1401→	}
  1402→
  1403→	return INDEX_NONE;
  1404→}
