	/** 불러오기 다이얼로그에서 슬롯 삭제 요청 시 호출 */
	UFUNCTION()
	void OnSlotDeleteRequested(const FString& SlotName);

	/** 전체 삭제 버튼 클릭 핸들러 */
	UFUNCTION()
	void OnClearClicked();

