+{
+	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
+	if (!DataProvider)
+	{
+		UE_LOG(LogWjWorldPlacement, Warning, TEXT("PlacementComponent: ClearAllPlacedObjects - PlacementDataProvider not found"));
