+{
+	IWjWorldPlacementDataProvider* DataProvider = GetPlacementDataProvider();
+	if (!DataProvider)
+	{
+		return 0;
+	}
+
+	int32 Count = 0;
+	for (const FPlacedObjectSaveEntry& Entry : DataProvider->GetPlacedObjects())
+	{
+		if (Entry.ObjectId == ObjectId)
+		{
+			++Count;
+		}
+	}
+	return Count;
+}
