   112→		if (UWjWorldCurrencySubsystem* CurrencySub = GI->GetSubsystem<UWjWorldCurrencySubsystem>())
   113→		{
   114→			CurrencySub->OnCurrencyPurchaseComplete.RemoveDynamic(this, &UCosmeticMainWindow::OnCurrencyPurchaseComplete);
   115→			CurrencySub->OnCurrencyPurchaseComplete.AddDynamic(this, &UCosmeticMainWindow::OnCurrencyPurchaseComplete);
   116→		}
   117→	}
   118→
   119→	UE_LOG(LogWjWorldCosmetic, Log, TEXT("CosmeticMainWindow: NativeConstruct completed"));
   120→}
