   286→void AWjWorldCharacterBase::Move(const FInputActionValue& Value)
   287→{
   288→	const FVector2D MoveVector = Value.Get<FVector2D>();
   289→	
   290→	if (Controller == nullptr || MoveVector.Length() <= 0.0f)
   291→	{
   292→		return;
   293→	}
   294→	
   295→	if (CameraMode == WjWorldGameplayTag::Camera_ThirdPerson())
   296→	{
   297→		APlayerController* PC = GetController<APlayerController>();
   298→		if (PC && PC->PlayerCameraManager)
   299→		{
   300→			//FRotator CameraRotation = PC->PlayerCameraManager->GetCameraRotation();
   301→			FRotator CameraRotation = GamePlayCamera->GetEvaluatedCameraRotation();
   302→
   303→			const FRotator YawRotation(0.0f, CameraRotation.Yaw, 0.0f);
   304→
   305→			const FVector ForwardDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X);
   306→			const FVector RightDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);
   307→
   308→			AddMovementInput(ForwardDirection, MoveVector.Y);
   309→			AddMovementInput(RightDirection, MoveVector.X);
   310→		}
   311→	}
   312→	else if (CameraMode == WjWorldGameplayTag::Camera_FirstPerson())
   313→	{
   314→		const FRotator ControlRotation = GetActorRotation();
   315→		const FRotator YawRotation(0.0f, ControlRotation.Yaw, 0.0f);
   316→
   317→		const FVector ForwardDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X);
   318→		const FVector RightDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);
   319→
   320→		AddMovementInput(ForwardDirection, MoveVector.Y);
   321→		AddMovementInput(RightDirection, MoveVector.X);
   322→	}
   323→	else if (CameraMode == WjWorldGameplayTag::Camera_TopDown())
   324→	{
   325→		// TopDown: 월드 좌표계 기준으로 이동
   326→		// 카메라가 회전해도 WASD는 항상 월드 방향 기준
   327→		const FRotator YawRotation(0.0f, 0.0f, 0.0f); // 월드 좌표계
   328→
   329→		const FVector ForwardDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::X); // (1, 0, 0)
   330→		const FVector RightDirection = FRotationMatrix(YawRotation).GetUnitAxis(EAxis::Y);   // (0, 1, 0)
   331→
   332→		AddMovementInput(ForwardDirection, MoveVector.Y); // W/S
   333→		AddMovementInput(RightDirection, MoveVector.X);   // D/A
   334→	}
   335→}
