    83→void AWjWorldCharacterPlay::OnEliminated()
    84→{
    85→	if (bIsEliminated)
    86→	{
    87→		return; // 이미 사망한 경우 무시
    88→	}
    89→
    90→	// Shield 버프 체크 (있으면 소모하고 제거 무시)
    91→	if (AbilitySystemComponent.IsValid() && AbilitySystemComponent->HasMatchingGameplayTag(WjWorldGameplayTag::Buff_Shield()))
    92→	{
    93→		AbilitySystemComponent->RemoveLooseGameplayTag(WjWorldGameplayTag::Buff_Shield());
    94→		UE_LOG(LogWjWorld, Log, TEXT("AWjWorldCharacterPlay::OnEliminated - Shield consumed, elimination prevented"));
    95→		return;
    96→	}
    97→
    98→	bIsEliminated = true;
    99→
   100→	// ASC에 State.Eliminated 태그 추가 → 어빌리티 활성화 차단
   101→	if (AbilitySystemComponent.IsValid())
   102→	{
   103→		AbilitySystemComponent->AddLooseGameplayTag(WjWorldGameplayTag::State_Eliminated());
   104→		AbilitySystemComponent->CancelAllAbilities();
   105→	}
   106→
   107→	// PlayerState 데이터 컴포넌트 업데이트는 각 GameRule에서 처리
   108→
   109→	HandleEliminationEffects();
   110→}
