   120→void AWjWorldCharacterPlay::HandleEliminationEffects()
   121→{
   122→	// 움직임 비활성화
   123→	if (UCharacterMovementComponent* MovementComp = GetCharacterMovement())
   124→	{
   125→		MovementComp->DisableMovement();
   126→		MovementComp->StopMovementImmediately();
   127→	}
   128→
   129→	// 관전 대상 전환 (로컬 컨트롤러에서만)
   130→	// DisableInput은 사용하지 않음 — 카메라 Yaw 입력까지 차단되어 관전 시 회전 불가
   131→	// 이동은 이미 위에서 DisableMovement()로 차단, 어빌리티는 State_Eliminated 태그 + CancelAllAbilities로 차단
   132→	APlayerController* PC = Cast<APlayerController>(GetController());
   133→	if (PC && PC->IsLocalController())
   134→	{
   135→		// 살아있는 다른 플레이어 찾아서 관전
   136→		AGameStateBase* GS = GetWorld()->GetGameState<AGameStateBase>();
   137→		if (GS)
   138→		{
   139→			for (APlayerState* PS : GS->PlayerArray)
   140→			{
   141→				if (!PS || PS == PC->PlayerState) continue;
   142→				APawn* OtherPawn = PS->GetPawn();
   143→				AWjWorldCharacterPlay* OtherChar = Cast<AWjWorldCharacterPlay>(OtherPawn);
   144→				if (OtherChar && !OtherChar->IsEliminated())
   145→				{
   146→					PC->SetViewTargetWithBlend(OtherChar, 0.5f);
   147→					PC->SetControlRotation(OtherChar->GetActorRotation());
   148→					UE_LOG(LogWjWorld, Log, TEXT("HandleEliminationEffects: Spectating %s"), *PS->GetPlayerName());
   149→					break;
   150→				}
   151→			}
   152→		}
   153→	}
   154→
   155→	// 1초 후 캐릭터 파괴
   156→	if (GetWorld())
   157→	{
   158→		FTimerHandle DestroyHandle;
   159→		GetWorld()->GetTimerManager().SetTimer(DestroyHandle, [this]()
   160→		{
   161→			Destroy();
   162→		}, 1.0f, false);
   163→	}
   164→}
