   166→void AWjWorldCharacterPlay::OnRep_PlayerState()
   167→{
   168→	Super::OnRep_PlayerState();
   169→
   170→	// ASC 초기화 (CharacterPlay 전용)
   171→	APlayerState* WJPlayerState = GetPlayerState<AWjWorldPlayerStatePlay>();
   172→	IAbilitySystemInterface* AbilitySystemInterface = Cast<IAbilitySystemInterface>(WJPlayerState);
   173→	if (AbilitySystemInterface)
   174→	{
   175→		AbilitySystemComponent = Cast<UWjWorldAbilitySystemComponent>(AbilitySystemInterface->GetAbilitySystemComponent());
   176→		if (AbilitySystemComponent.IsValid())
   177→		{
   178→			// 클라이언트에서도 ActorInfo 초기화 필요 (어빌리티 입력 처리를 위해)
   179→			AbilitySystemComponent->InitAbilityActorInfo(WJPlayerState, this);
   180→
   181→			// Confirm/Cancel InputID 설정
   182→			AbilitySystemComponent->GenericConfirmInputID = static_cast<int32>(EWjWorldAbilityInputID::Confirm);
   183→			AbilitySystemComponent->GenericCancelInputID = static_cast<int32>(EWjWorldAbilityInputID::Cancel);
   184→
   185→			// 클라이언트 공통 초기화 (어빌리티 부여는 Initialize 내부에서 Authority 체크)
   186→			FLoadSoftObjectPathAsyncDelegate SetupDataLoadDel;
   187→			SetupDataLoadDel.BindUObject(this, &ThisClass::OnSetupDataAssetLoaded);
   188→			SetupDataAsset.LoadAsync(SetupDataLoadDel);
   189→		}
   190→	}
   191→
   192→	// 코스메틱은 Super::OnRep_PlayerState()에서 처리됨 (CharacterBase)
   193→}
