   377→void AWjWorldCharacterPlay::UpdateLiftedBrickVisual()
   378→{
   379→	if (!LiftedBrickMeshComponent)
   380→	{
   381→		return;
   382→	}
   383→
   384→	if (bIsCarryingBrick && CarriedBrickMesh)
   385→	{
   386→		LiftedBrickMeshComponent->SetStaticMesh(CarriedBrickMesh);
   387→		LiftedBrickMeshComponent->SetRelativeScale3D(CarriedBrickScale * 0.3f);
   388→		LiftedBrickMeshComponent->SetVisibility(true);
   389→
   390→		// Dynamic Material Instance 생성 및 색상 적용
   391→		if (LiftedBrickMeshComponent->GetNumMaterials() > 0)
   392→		{
   393→			UMaterialInterface* BaseMaterial = LiftedBrickMeshComponent->GetMaterial(0);
   394→			if (BaseMaterial)
   395→			{
   396→				LiftedBrickDynamicMaterial = LiftedBrickMeshComponent->CreateAndSetMaterialInstanceDynamic(0);
   397→				if (LiftedBrickDynamicMaterial)
   398→				{
   399→					LiftedBrickDynamicMaterial->SetVectorParameterValue(FName("BaseColor"), CarriedBrickColor);
   400→				}
   401→			}
   402→		}
   403→	}
   404→	else
   405→	{
   406→		LiftedBrickMeshComponent->SetVisibility(false);
   407→		LiftedBrickMeshComponent->SetStaticMesh(nullptr);
   408→		LiftedBrickDynamicMaterial = nullptr;
   409→	}
   410→}
