   412→void AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex_Implementation(int32 GridX, int32 GridY)
   413→{
   414→	UE_LOG(LogWjWorld, Log, TEXT("AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex - GridIndex: (%d, %d)"), GridX, GridY);
   415→
   416→	UWorld* World = GetWorld();
   417→	if (!World)
   418→	{
   419→		return;
   420→	}
   421→
   422→	// 서버에서 WallDesc 가져오기
   423→	FWjWorldWallDescription ServerWallDesc;
   424→	AWjWorldGameModePlay* GameModePlay = World->GetAuthGameMode<AWjWorldGameModePlay>();
   425→	if (GameModePlay)
   426→	{
   427→		UWjWorldGameRuleApproachingWall* GameRule = GameModePlay->GetCurrentGameRule<UWjWorldGameRuleApproachingWall>();
   428→		if (GameRule)
   429→		{
   430→			ServerWallDesc = GameRule->GetWallDesc();
   431→		}
   432→	}
   433→
   434→	// WallDesc가 유효하지 않으면 실패
   435→	if (ServerWallDesc.BrickSize.IsZero() || ServerWallDesc.ColumnNum == 0)
   436→	{
   437→		UE_LOG(LogWjWorld, Warning, TEXT("AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex - Invalid WallDesc"));
   438→		return;
   439→	}
   440→
   441→	// 그리드 범위 체크
   442→	if (GridX < 0 || GridX >= ServerWallDesc.ColumnNum ||
   443→		GridY < 0 || GridY >= ServerWallDesc.RowNum)
   444→	{
   445→		UE_LOG(LogWjWorld, Warning, TEXT("AWjWorldCharacterPlay::ServerSpawnBrickAtGridIndex - Invalid GridIndex (%d, %d) for grid %dx%d"),
   446→			GridX, GridY, ServerWallDesc.ColumnNum, ServerWallDesc.RowNum);
   447→		return;
   448→	}
   449→
   450→	// 충전 소모 (ASC에서)
   451→	if (AbilitySystemComponent.IsValid())
   452→	{
   453→		const UGameplayEffect* CostGE = UGE_SpawnBrickChargeCost::StaticClass()->GetDefaultObject<UGameplayEffect>();
   454→		if (CostGE)
   455→		{
   456→			FGameplayEffectContextHandle ContextHandle = AbilitySystemComponent->MakeEffectContext();
   457→			FGameplayEffectSpec Spec(CostGE, ContextHandle, 1.f);
   458→			AbilitySystemComponent->ApplyGameplayEffectSpecToSelf(Spec);
   459→		}
   460→	}
   461→
   462→	FIntPoint SpawnIndexPoint(GridX, GridY);
   463→	FVector SpawnPosition = UWjWorldBrickSpawner::CalculateBrickPosition(
   464→		GridX,
   465→		GridY,
   466→		ServerWallDesc.ColumnNum,
   467→		ServerWallDesc.RowNum,
   468→		ServerWallDesc.CenterOffset,
   469→		ServerWallDesc.BrickSize
   470→	);
   471→
   472→	FWjWorldBrickProperties BrickProperties;
   473→	BrickProperties.BrickType = FMath::RandBool() ? EWjWorldBrickType::Moving : EWjWorldBrickType::Destructible;
   474→	BrickProperties.BrickMoveType = EWjWorldBrickMoveType::Standard;
   475→	BrickProperties.Size = ServerWallDesc.BrickSize;
   476→	BrickProperties.Color = BrickProperties.GetColorWithBrickType();
   477→	BrickProperties.SpawnedGridPosition = SpawnIndexPoint;
   478→	BrickProperties.CenterOffset = ServerWallDesc.CenterOffset;
   479→	BrickProperties.ColumnNum = ServerWallDesc.ColumnNum;
   480→	BrickProperties.RowNum = ServerWallDesc.RowNum;
   481→
   482→	// Destructible 벽돌은 DeveloperSettings에서 MaxHP 설정
   483→	if (BrickProperties.BrickType == EWjWorldBrickType::Destructible)
   484→	{
   485→		BrickProperties.MaxHP = GetDefault<UWjWorldDeveloperSettings>()->DestructibleBrickDefaultHP;
   486→	}
   487→
   488→	UWjWorldBrickSpawner::SpawnBrickActor(World, BrickProperties, GridX, GridY);
   489→
   490→	// GameplayCue 실행 (사운드/VFX)
   491→	if (AbilitySystemComponent.IsValid())
   492→	{
   493→		FGameplayCueParameters CueParams;
   494→		CueParams.Location = SpawnPosition;
   495→		AbilitySystemComponent->ExecuteGameplayCue(WjWorldGameplayTag::GameplayCue_Ability_SpawnBrick(), CueParams);
   496→	}
   497→}
