    23→bool UGA_DoubleJump::CanActivateAbility(const FGameplayAbilitySpecHandle Handle, const FGameplayAbilityActorInfo* ActorInfo, const FGameplayTagContainer* SourceTags, const FGameplayTagContainer* TargetTags, OUT FGameplayTagContainer* OptionalRelevantTags) const
    24→{
    25→	// Base 어빌리티 체크 (제거 상태, 게임 페이즈, 쿨다운 등) - GA_Jump의 CanJump() 체크를 건너뜀
    26→	if (!UWjWorldGameplayAbilityBase::CanActivateAbility(Handle, ActorInfo, SourceTags, TargetTags, OptionalRelevantTags))
    27→	{
    28→		return false;
    29→	}
    30→
    31→	const ACharacter* Character = CastChecked<ACharacter>(ActorInfo->AvatarActor.Get(), ECastCheckedType::NullAllowed);
    32→	if (!Character)
    33→	{
    34→		return false;
    35→	}
    36→
    37→	UCharacterMovementComponent* MovementComp = Character->GetCharacterMovement();
    38→	if (!MovementComp)
    39→	{
    40→		return false;
    41→	}
    42→
    43→	// 지상이면 항상 허용 (카운트 리셋)
    44→	if (!MovementComp->IsFalling())
    45→	{
    46→		CurrentJumpCount = 0;
    47→		return true;
    48→	}
    49→
    50→	// 공중이면 카운트 체크
    51→	return CurrentJumpCount < MaxJumpCount;
    52→}
